using System.Text.Json.Nodes;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using VirtualCompany.Domain.Entities;
using VirtualCompany.Domain.Enums;

namespace VirtualCompany.Infrastructure.Persistence;

internal sealed class OperatingCycleConfiguration : IEntityTypeConfiguration<OperatingCycle>
{
    public void Configure(EntityTypeBuilder<OperatingCycle> b)
    {
        b.ToTable("operating_cycles"); b.HasKey(x => x.Id); Ids(b); b.Property(x => x.TriggerType).HasColumnName("trigger_type").HasMaxLength(64).IsRequired();
        b.Property(x => x.TriggerReference).HasColumnName("trigger_reference").HasMaxLength(256); b.Property(x => x.CoordinatorAgentId).HasColumnName("coordinator_agent_id").IsRequired();
        b.Property(x => x.Status).HasColumnName("status").HasConversion(x => x.ToStorageValue(), x => OperatingCycleStatusValues.Parse(x)).HasMaxLength(32).IsRequired();
        b.Property(x => x.ConfigurationVersion).HasColumnName("configuration_version"); b.Property(x => x.CorrelationId).HasColumnName("correlation_id").HasMaxLength(128).IsRequired();
        b.Property(x => x.IdempotencyKey).HasColumnName("idempotency_key").HasMaxLength(200).IsRequired(); b.Property(x => x.SnapshotId).HasColumnName("snapshot_id");
        b.Property(x => x.ModelCallsUsed).HasColumnName("model_calls_used"); b.Property(x => x.ToolCallsUsed).HasColumnName("tool_calls_used"); b.Property(x => x.TasksCreated).HasColumnName("tasks_created");
        b.Property(x => x.MonetaryBudgetUsed).HasColumnName("monetary_budget_used").HasPrecision(19, 4); b.Property(x => x.FailureCode).HasColumnName("failure_code").HasMaxLength(100); b.Property(x => x.FailureSummary).HasColumnName("failure_summary").HasMaxLength(2000);
        b.Property(x => x.RequestedUtc).HasColumnName("requested_at"); b.Property(x => x.StartedUtc).HasColumnName("started_at"); b.Property(x => x.CompletedUtc).HasColumnName("completed_at"); Times(b);
        b.HasIndex(x => new { x.CompanyId, x.IdempotencyKey }).IsUnique(); b.HasIndex(x => new { x.CompanyId, x.Status, x.RequestedUtc });
        b.HasOne(x => x.Company).WithMany().HasForeignKey(x => x.CompanyId).OnDelete(DeleteBehavior.Cascade); b.HasOne(x => x.CoordinatorAgent).WithMany().HasForeignKey(x => x.CoordinatorAgentId).OnDelete(DeleteBehavior.NoAction);
    }
    internal static void Ids<T>(EntityTypeBuilder<T> b) where T : class, ICompanyOwnedEntity { b.Property<Guid>("Id").HasColumnName("id"); b.Property(x => x.CompanyId).HasColumnName("company_id").IsRequired(); }
    internal static void Times<T>(EntityTypeBuilder<T> b) where T : class { b.Property<DateTime>("CreatedUtc").HasColumnName("created_at"); b.Property<DateTime>("UpdatedUtc").HasColumnName("updated_at"); }
}

internal sealed class OperatingPlanConfiguration : IEntityTypeConfiguration<OperatingPlan>
{
    public void Configure(EntityTypeBuilder<OperatingPlan> b) { b.ToTable("operating_plans"); b.HasKey(x => x.Id); OperatingCycleConfiguration.Ids(b); b.Property(x => x.CycleId).HasColumnName("cycle_id"); b.Property(x => x.SupersedesPlanId).HasColumnName("supersedes_plan_id"); b.Property(x => x.Version).HasColumnName("version"); b.Property(x => x.Status).HasColumnName("status").HasConversion(x => x.ToStorageValue(), x => OperatingPlanStatusValues.Parse(x)).HasMaxLength(32); b.Property(x => x.Objective).HasColumnName("objective").HasMaxLength(2000); b.Property(x => x.RationaleSummary).HasColumnName("rationale_summary").HasMaxLength(4000); b.Property(x => x.Uncertainty).HasColumnName("uncertainty_json").HasJsonConversion<Dictionary<string, JsonNode?>>().HasDefaultValueSql(CompanyJsonColumnConfiguration.JsonObjectDefault); OperatingCycleConfiguration.Times(b); b.Property(x => x.ReviewedUtc).HasColumnName("reviewed_at"); b.Property(x => x.CommittedUtc).HasColumnName("committed_at"); b.HasIndex(x => new { x.CompanyId, x.CycleId, x.Version }).IsUnique(); b.HasOne(x => x.Company).WithMany().HasForeignKey(x => x.CompanyId).OnDelete(DeleteBehavior.Cascade); b.HasOne(x => x.Cycle).WithMany(x => x.Plans).HasForeignKey(x => x.CycleId).OnDelete(DeleteBehavior.NoAction); b.HasOne(x => x.SupersedesPlan).WithMany().HasForeignKey(x => x.SupersedesPlanId).OnDelete(DeleteBehavior.NoAction); }
}

