{
    public void Configure(EntityTypeBuilder<OperatingInitiative> b) { b.ToTable("operating_initiatives"); b.HasKey(x => x.Id); OperatingCycleConfiguration.Ids(b); b.Property(x => x.PlanId).HasColumnName("plan_id"); b.Property(x => x.GoalId).HasColumnName("goal_id"); b.Property(x => x.Title).HasColumnName("title").HasMaxLength(200); b.Property(x => x.DesiredOutcome).HasColumnName("desired_outcome").HasMaxLength(2000); b.Property(x => x.Priority).HasColumnName("priority").HasConversion(x => x.ToStorageValue(), x => CompanyGoalPriorityValues.Parse(x)).HasMaxLength(32); b.Property(x => x.Status).HasColumnName("status").HasConversion(x => x.ToStorageValue(), x => OperatingInitiativeStatusValues.Parse(x)).HasMaxLength(32); b.Property(x => x.CompletionEvidence).HasColumnName("completion_evidence").HasMaxLength(2000); b.Property(x => x.OwnerAgentId).HasColumnName("owner_agent_id"); b.Property(x => x.TargetUtc).HasColumnName("target_at"); b.Property(x => x.Budget).HasColumnName("budget").HasPrecision(19, 4); b.Property(x => x.TaskId).HasColumnName("task_id"); b.Property(x => x.WorkflowInstanceId).HasColumnName("workflow_instance_id"); b.Property(x => x.Version).HasColumnName("version").IsConcurrencyToken(); OperatingCycleConfiguration.Times(b); b.HasIndex(x => new { x.CompanyId, x.Status, x.TargetUtc }); b.HasOne(x => x.Plan).WithMany(x => x.Initiatives).HasForeignKey(x => x.PlanId).OnDelete(DeleteBehavior.Cascade); b.HasOne(x => x.Goal).WithMany().HasForeignKey(x => x.GoalId).OnDelete(DeleteBehavior.NoAction); b.HasOne(x => x.OwnerAgent).WithMany().HasForeignKey(x => x.OwnerAgentId).OnDelete(DeleteBehavior.NoAction); b.HasOne(x => x.Task).WithMany().HasForeignKey(x => x.TaskId).OnDelete(DeleteBehavior.NoAction); b.HasOne(x => x.WorkflowInstance).WithMany().HasForeignKey(x => x.WorkflowInstanceId).OnDelete(DeleteBehavior.NoAction); }
}

