    public void Configure(EntityTypeBuilder<OperatingPlanDependency> b) { b.ToTable("operating_plan_dependencies"); b.HasKey(x => x.Id); OperatingCycleConfiguration.Ids(b); b.Property(x => x.PlanId).HasColumnName("plan_id"); b.Property(x => x.InitiativeId).HasColumnName("initiative_id"); b.Property(x => x.DependsOnInitiativeId).HasColumnName("depends_on_initiative_id"); b.HasIndex(x => new { x.CompanyId, x.PlanId, x.InitiativeId, x.DependsOnInitiativeId }).IsUnique(); b.HasOne(x => x.Plan).WithMany().HasForeignKey(x => x.PlanId).OnDelete(DeleteBehavior.Cascade); b.HasOne<OperatingInitiative>().WithMany().HasForeignKey(x => x.InitiativeId).OnDelete(DeleteBehavior.NoAction); b.HasOne<OperatingInitiative>().WithMany().HasForeignKey(x => x.DependsOnInitiativeId).OnDelete(DeleteBehavior.NoAction); }
