    public void Configure(EntityTypeBuilder<OperatingDecision> b) { b.ToTable("operating_decisions"); b.HasKey(x => x.Id); OperatingCycleConfiguration.Ids(b); b.Property(x => x.PlanId).HasColumnName("plan_id"); b.Property(x => x.InitiativeId).HasColumnName("initiative_id"); b.Property(x => x.ActionClass).HasColumnName("action_class").HasConversion(x => x.ToStorageValue(), x => OperatingActionClassValues.Parse(x)).HasMaxLength(32); b.Property(x => x.ActionType).HasColumnName("action_type").HasMaxLength(128); b.Property(x => x.TargetType).HasColumnName("target_type").HasMaxLength(100); b.Property(x => x.TargetId).HasColumnName("target_id").HasMaxLength(200); b.Property(x => x.ProposedAgentId).HasColumnName("proposed_agent_id"); b.Property(x => x.RationaleSummary).HasColumnName("rationale_summary").HasMaxLength(2000); b.Property(x => x.Confidence).HasColumnName("confidence").HasPrecision(5, 4); b.Property(x => x.RiskLevel).HasColumnName("risk_level").HasMaxLength(32); b.Property(x => x.ApprovalRequired).HasColumnName("approval_required"); b.Property(x => x.IdempotencyKey).HasColumnName("idempotency_key").HasMaxLength(200); b.Property(x => x.CreatedUtc).HasColumnName("created_at"); b.HasIndex(x => new { x.CompanyId, x.IdempotencyKey }).IsUnique(); b.HasOne(x => x.Plan).WithMany(x => x.Decisions).HasForeignKey(x => x.PlanId).OnDelete(DeleteBehavior.Cascade); b.HasOne<OperatingInitiative>().WithMany().HasForeignKey(x => x.InitiativeId).OnDelete(DeleteBehavior.NoAction); b.HasOne<Agent>().WithMany().HasForeignKey(x => x.ProposedAgentId).OnDelete(DeleteBehavior.NoAction); }
